package kosanku.model;

public class Rooms {
    private int id;
    private String roomNumber;
    private String type;
    private double price;
    private String facilities;
    private RoomStatus status;

    // Matches the database default ('Tersedia')
    public Rooms() {
        this.status = RoomStatus.TERSEDIA;
    }

    // For inserting a new room (id is generated by the database)
    public Rooms(String roomNumber, String type, double price, String facilities, RoomStatus status) {
        this.roomNumber = roomNumber;
        this.type = type;
        this.price = price;
        this.facilities = facilities;
        this.status = status;
    }

    // Full constructor with ID (for reading/updating data from the database)
    public Rooms(int id, String roomNumber, String type, double price, String facilities, RoomStatus status) {
        this.id = id;
        this.roomNumber = roomNumber;
        this.type = type;
        this.price = price;
        this.facilities = facilities;
        this.status = status;
    }

    public int getId() {return id;}
    public String getRoomNumber() {return roomNumber;}
    public String getType() {return type;}
    public double getPrice() {return price;}
    public String getFacilities() {return facilities;}
    public RoomStatus getStatus() {return status;}

    public void setId(int id) {this.id = id;}
    public void setRoomNumber(String roomNumber) {this.roomNumber = roomNumber;}
    public void setType(String type) {this.type = type;}
    public void setPrice(double price) {this.price = price;}
    public void setFacilities(String facilities) {this.facilities = facilities;}
    public void setStatus(RoomStatus status) {this.status = status;}

    @Override
    public String toString() {
        return roomNumber + " - " + type + " (" + status + ")";
    }
}
